Here is a complete, enterprise-grade, concurrent Log Ingestion and Analytics Pipeline written in C#. 

This implementation is fully realized, highly modular, robustly designed for high performance, and compiles out of the box in .NET 8+ without external dependencies.

---

### Architecture Overview

```
                                      [Concurrent Producers]
                                                │
                                                ▼
┌──────────────────────────────────────────────────────────────────────────────────────────────┐
│ SUBSYSTEM 1: HIGH-THROUGHPUT LOG COLLECTOR                                                   │
│   - Bounded BlockingCollection (Backpressure)                                                │
│   - Lock-Free Concurrent Performance Performance Counters (Interlocked)                      │
└───────────────────────────────────────┬──────────────────────────────────────────────────────┘
                                        │ (Consuming Enumerable / Thread-Safe Hand-off)
                                        ▼
┌──────────────────────────────────────────────────────────────────────────────────────────────┐
│ SYSTEM COORDINATOR (Pipeline Dispatcher)                                                     │
└───────────────────────┬──────────────────────────────────────────────────────────────┬───────┘
                        │                                                              │
                        ▼                                                              ▼
┌──────────────────────────────────────────────┐ ┌─────────────────────────────────────────────┐
│ SUBSYSTEM 2: REAL-TIME PATTERN MATCHER       │ │ SUBSYSTEM 3: PERSISTENT INDEXING SUBSYSTEM  │
│  - Compiled Regex Threat/Pattern Detection   │ │  - Dynamic Memory Buffering & Auto-Flush    │
│  - Thread-Safe Sliding Window Anomaly Engine │ │  - Thread-Safe GZip Compressing Writer      │
│  - Real-Time Anomaly Breach Events           │ │  - Structured Transactional Chunk Indexing  │
└──────────────────────────────────────────────┘ └─────────────────────────────────────────────┘
```

---

### Implementation

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

namespace EnterpriseLoggingPipeline
{
    #region Core Domain Models

    /// <summary>
    /// Represents the severity level of an ingested log.
    /// </summary>
    public enum LogSeverity
    {
        Trace,
        Debug,
        Info,
        Warning,
        Error,
        Critical
    }

    /// <summary>
    /// Structured representation of an internal Log Event.
    /// </summary>
    public record LogEvent(
        Guid Id,
        DateTime Timestamp,
        LogSeverity Severity,
        string Component,
        string Message,
        string RawPayload
    );

    /// <summary>
    /// Representation of historical logs stored inside a compressed physical file chunk.
    /// </summary>
    public record LogChunkMetadata(
        Guid ChunkId,
        DateTime StartTime,
        DateTime EndTime,
        long TotalRecords,
        string FilePath,
        long UncompressedSizeBytes,
        long CompressedSizeBytes
    );

    /// <summary>
    /// Event arguments raised when anomalies are detected in real-time.
    /// </summary>
    public class AnomalyDetectedEventArgs : EventArgs
    {
        public DateTime Timestamp { get; init; }
        public LogSeverity TargetSeverity { get; init; }
        public int ErrorCountInWindow { get; init; }
        public TimeSpan WindowDuration { get; init; }
        public string Message { get; init; } = string.Empty;
    }

    #endregion

    #region Subsystem 1: High-Throughput Log Collector

    public interface ILogCollector : IDisposable
    {
        bool TrySubmit(LogSeverity severity, string component, string message, string rawPayload);
        IReadOnlyDictionary<string, long> GetPerformanceMetrics();
        void StartProcessing(Func<LogEvent, Task> onEventProcessed, CancellationToken cancellationToken);
    }

    /// <summary>
    /// Thread-safe, lock-free log collector utilizing bounded BlockingCollections to enforce backpressure.
    /// </summary>
    public sealed class HighThroughputLogCollector : ILogCollector
    {
        private readonly BlockingCollection<LogEvent> _incomingQueue;
        private readonly int _maxCapacity;
        private Task? _consumerTask;

        // Thread-safe atomic metrics counters
        private long _ingestedCount;
        private long _droppedCount;
        private long _processedCount;

        public HighThroughputLogCollector(int maxCapacity = 50000)
        {
            _maxCapacity = maxCapacity;
            _incomingQueue = new BlockingCollection<LogEvent>(new ConcurrentQueue<LogEvent>(), _maxCapacity);
        }

        /// <summary>
        /// Attempts to submit a log. Enforces backpressure dropping patterns if the queue is saturated.
        /// </summary>
        public bool TrySubmit(LogSeverity severity, string component, string message, string rawPayload)
        {
            if (_incomingQueue.IsAddingCompleted)
            {
                Interlocked.Increment(ref _droppedCount);
                return false;
            }

            var logEvent = new LogEvent(
                Id: Guid.NewGuid(),
                Timestamp: DateTime.UtcNow,
                Severity: severity,
                Component: component,
                Message: message,
                RawPayload: rawPayload
            );

            // Attempt instantaneous add; if full, handle gracefully to avoid blocking high-performance producers indefinitely
            bool added = _incomingQueue.TryAdd(logEvent);
            if (added)
            {
                Interlocked.Increment(ref _ingestedCount);
            }
            else
            {
                Interlocked.Increment(ref _droppedCount);
            }

            return added;
        }

        /// <summary>
        /// Begins processing the internal pipeline asynchronously.
        /// </summary>
        public void StartProcessing(Func<LogEvent, Task> onEventProcessed, CancellationToken cancellationToken)
        {
            if (_consumerTask != null)
            {
                throw new InvalidOperationException("Collector consumer loop is already active.");
            }

            _consumerTask = Task.Run(async () =>
            {
                try
                {
                    // ConsumingEnumerable blocks efficiently until items are available or cancellation is requested.
                    foreach (var logEvent in _incomingQueue.GetConsumingEnumerable(cancellationToken))
                    {
                        try
                        {
                            await onEventProcessed(logEvent).ConfigureAwait(false);
                            Interlocked.Increment(ref _processedCount);
                        }
                        catch (Exception ex)
                        {
                            Console.Error.WriteLine($"[CollectorError] Failed executing consumer callback: {ex.Message}");
                        }
                    }
                }
                catch (OperationCanceledException)
                {
                    // Expected termination scenario on Cancel
                }
                finally
                {
                    _incomingQueue.CompleteAdding();
                }
            }, cancellationToken);
        }

        public IReadOnlyDictionary<string, long> GetPerformanceMetrics()
        {
            return new Dictionary<string, long>
            {
                { "Ingested", Interlocked.Read(ref _ingestedCount) },
                { "Dropped", Interlocked.Read(ref _droppedCount) },
                { "Processed", Interlocked.Read(ref _processedCount) },
                { "CurrentQueueDepth", _incomingQueue.Count },
                { "MaxCapacity", _maxCapacity }
            };
        }

        public void Dispose()
        {
            _incomingQueue.CompleteAdding();
            try
            {
                _consumerTask?.Wait(TimeSpan.FromSeconds(5));
            }
            catch (Exception) { /* Ignored during teardown */ }
            _incomingQueue.Dispose();
            _consumerTask?.Dispose();
        }
    }

    #endregion

    #region Subsystem 2: Real-Time Pattern Matcher & Anomaly Engine

    public interface IRealTimePatternMatcher
    {
        event EventHandler<AnomalyDetectedEventArgs> OnAnomalyDetected;
        void RegisterThreatPattern(string name, string regexPattern);
        void Analyze(LogEvent logEvent);
    }

    /// <summary>
    /// Combines ultra-high-speed compiled regex matching with an atomic sliding window anomaly engine.
    /// </summary>
    public sealed class RealTimePatternMatcher : IRealTimePatternMatcher
    {
        private readonly ConcurrentDictionary<string, Regex> _threatSignatures = new();
        private readonly ConcurrentQueue<DateTime> _anomalySlidingWindow = new();

        private readonly TimeSpan _windowDuration;
        private readonly int _anomalyThreshold;
        private readonly LogSeverity _anomalyTargetSeverity;

        public event EventHandler<AnomalyDetectedEventArgs>? OnAnomalyDetected;

        public RealTimePatternMatcher(TimeSpan windowDuration, int anomalyThreshold, LogSeverity targetSeverity = LogSeverity.Error)
        {
            _windowDuration = windowDuration;
            _anomalyThreshold = anomalyThreshold;
            _anomalyTargetSeverity = targetSeverity;
        }

        /// <summary>
        /// Registers a pre-compiled, culture-invariant threat pattern.
        /// </summary>
        public void RegisterThreatPattern(string name, string regexPattern)
        {
            var compiledRegex = new Regex(
                regexPattern, 
                RegexOptions.Compiled | RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Singleline
            );
            _threatSignatures[name] = compiledRegex;
        }

        /// <summary>
        /// Performs deep packet inspection on payload patterns and runs sliding-window time calculations.
        /// </summary>
        public void Analyze(LogEvent logEvent)
        {
            // 1. Thread-safe Regex Threat Pattern Inspection
            foreach (var (ruleName, regex) in _threatSignatures)
            {
                if (regex.IsMatch(logEvent.Message) || regex.IsMatch(logEvent.RawPayload))
                {
                    TriggerAnomaly(logEvent.Timestamp, $"[THREAT DETECTED] Match on rule [{ruleName}] by log ID {logEvent.Id}");
                }
            }

            // 2. Sliding Window Severity Calculation
            if (logEvent.Severity >= _anomalyTargetSeverity)
            {
                DateTime now = DateTime.UtcNow;
                _anomalySlidingWindow.Enqueue(now);

                // Prune expired events outside our active window
                DateTime boundary = now - _windowDuration;
                while (_anomalySlidingWindow.TryPeek(out DateTime earliest) && earliest < boundary)
                {
                    _anomalySlidingWindow.TryDequeue(out _);
                }

                // Check for dynamic rate threshold violations
                int currentCount = _anomalySlidingWindow.Count;
                if (currentCount >= _anomalyThreshold)
                {
                    TriggerAnomaly(
                        now, 
                        $"[VOLUME ANOMALY] Breach detected! Encountered {currentCount} logs matching severity level '{_anomalyTargetSeverity}' inside a sliding window of {_windowDuration.TotalSeconds} seconds."
                    );
                }
            }
        }

        private void TriggerAnomaly(DateTime timestamp, string message)
        {
            var handler = OnAnomalyDetected;
            if (handler != null)
            {
                // Dispatch notifications asynchronously to avoid blocking the caller's execution thread
                Task.Run(() => handler(this, new AnomalyDetectedEventArgs
                {
                    Timestamp = timestamp,
                    TargetSeverity = _anomalyTargetSeverity,
                    ErrorCountInWindow = _anomalySlidingWindow.Count,
                    WindowDuration = _windowDuration,
                    Message = message
                }));
            }
        }
    }

    #endregion

    #region Subsystem 3: Persistent Indexing Subsystem

    public interface ILogIndexer : IDisposable
    {
        Task WriteAsync(LogEvent logEvent);
        Task FlushAllAsync();
        IEnumerable<LogEvent> QueryHistoricalLogs(DateTime startTime, DateTime endTime);
    }

    /// <summary>
    /// Thread-safe, compressed chunking persistent writer with ReaderWriterLockSlim coordination.
    /// Writes chunks serialized to GZip formats, indexing them natively for high performance lookups.
    /// </summary>
    public sealed class CompressedLogIndexer : ILogIndexer
    {
        private readonly string _storageDirectory;
        private readonly int _maxLogsPerChunk;
        private readonly TimeSpan _maxChunkAge;

        // Multi-reader, single-writer synchronizer safeguarding system indices and disk states
        private readonly ReaderWriterLockSlim _indexLock = new();
        private readonly List<LogChunkMetadata> _metadataIndex = new();

        private readonly List<LogEvent> _memoryBuffer = new();
        private DateTime _currentChunkCreatedTime = DateTime.UtcNow;
        private readonly string _metadataFilePath;

        public CompressedLogIndexer(string storageDirectory, int maxLogsPerChunk = 5000, TimeSpan? maxChunkAge = null)
        {
            _storageDirectory = storageDirectory;
            _maxLogsPerChunk = maxLogsPerChunk;
            _maxChunkAge = maxChunkAge ?? TimeSpan.FromMinutes(10);

            Directory.CreateDirectory(_storageDirectory);
            _metadataFilePath = Path.Combine(_storageDirectory, "index.json");

            LoadMetadataIndex();
        }

        /// <summary>
        /// Inserts logs into buffer and flushes automatically if capacity/age limits are crossed.
        /// </summary>
        public async Task WriteAsync(LogEvent logEvent)
        {
            bool triggerFlush = false;

            _indexLock.EnterWriteLock();
            try
            {
                _memoryBuffer.Add(logEvent);

                bool timeExceeded = DateTime.UtcNow - _currentChunkCreatedTime >= _maxChunkAge;
                bool countExceeded = _memoryBuffer.Count >= _maxLogsPerChunk;

                if (countExceeded || timeExceeded)
                {
                    triggerFlush = true;
                }
            }
            finally
            {
                _indexLock.ExitWriteLock();
            }

            if (triggerFlush)
            {
                await FlushAllAsync().ConfigureAwait(false);
            }
        }

        /// <summary>
        /// Commits all in-memory buffers safely to disk as a GZip compressed stream.
        /// </summary>
        public async Task FlushAllAsync()
        {
            List<LogEvent> logsToFlush;
            _indexLock.EnterWriteLock();
            try
            {
                if (_memoryBuffer.Count == 0) return;

                logsToFlush = new List<LogEvent>(_memoryBuffer);
                _memoryBuffer.Clear();
                _currentChunkCreatedTime = DateTime.UtcNow;
            }
            finally
            {
                _indexLock.ExitWriteLock();
            }

            if (logsToFlush.Count == 0) return;

            Guid chunkId = Guid.NewGuid();
            string chunkFileName = $"chunk_{chunkId:N}.bin.gz";
            string chunkFilePath = Path.Combine(_storageDirectory, chunkFileName);

            long uncompressedSize = 0;
            long compressedSize = 0;

            // Serialize and compress the target block
            using (var memoryStream = new MemoryStream())
            {
                using (var writer = new Utf8JsonWriter(memoryStream, new JsonWriterOptions { Indented = false }))
                {
                    JsonSerializer.Serialize(writer, logsToFlush);
                }

                uncompressedSize = memoryStream.Length;
                memoryStream.Position = 0;

                // Write compressed data to physical storage with exclusive OS file locking
                using (var fileStream = new FileStream(chunkFilePath, FileMode.Create, FileAccess.Write, FileShare.None))
                using (var gzipStream = new GZipStream(fileStream, CompressionMode.Compress))
                {
                    await memoryStream.CopyToAsync(gzipStream).ConfigureAwait(false);
                    await gzipStream.FlushAsync().ConfigureAwait(false);
                    compressedSize = fileStream.Length;
                }
            }

            var metadata = new LogChunkMetadata(
                ChunkId: chunkId,
                StartTime: logsToFlush.Min(l => l.Timestamp),
                EndTime: logsToFlush.Max(l => l.Timestamp),
                TotalRecords: logsToFlush.Count,
                FilePath: chunkFilePath,
                UncompressedSizeBytes: uncompressedSize,
                CompressedSizeBytes: compressedSize
            );

            _indexLock.EnterWriteLock();
            try
            {
                _metadataIndex.Add(metadata);
                SaveMetadataIndex();
            }
            finally
            {
                _indexLock.ExitWriteLock();
            }
        }

        /// <summary>
        /// Reads indexed ranges safely across multiple parallel reader threads.
        /// </summary>
        public IEnumerable<LogEvent> QueryHistoricalLogs(DateTime startTime, DateTime endTime)
        {
            List<LogChunkMetadata> eligibleChunks;

            _indexLock.EnterReadLock();
            try
            {
                // Quickly scan indices to pinpoint target files (skips reading irrelevant disk sectors)
                eligibleChunks = _metadataIndex
                    .Where(chunk => chunk.EndTime >= startTime && chunk.StartTime <= endTime)
                    .ToList();
            }
            finally
            {
                _indexLock.ExitReadLock();
            }

            foreach (var chunk in eligibleChunks)
            {
                if (!File.Exists(chunk.FilePath)) continue;

                List<LogEvent>? deserializedLogs = null;

                // Open with shared read locks so multiple concurrent lookups don't crash
                using (var fileStream = new FileStream(chunk.FilePath, FileMode.Open, FileAccess.Read, FileShare.Read))
                using (var gzipStream = new GZipStream(fileStream, CompressionMode.Decompress))
                using (var memoryStream = new MemoryStream())
                {
                    gzipStream.CopyTo(memoryStream);
                    memoryStream.Position = 0;
                    deserializedLogs = JsonSerializer.Deserialize<List<LogEvent>>(memoryStream);
                }

                if (deserializedLogs != null)
                {
                    foreach (var log in deserializedLogs)
                    {
                        if (log.Timestamp >= startTime && log.Timestamp <= endTime)
                        {
                            yield return log;
                        }
                    }
                }
            }
        }

        private void SaveMetadataIndex()
        {
            try
            {
                // Write transactionally: Save to temporary file then swap instantly to avoid partial-write corruptions
                string tempPath = _metadataFilePath + ".tmp";
                string json = JsonSerializer.Serialize(_metadataIndex, new JsonSerializerOptions { WriteIndented = true });
                File.WriteAllText(tempPath, json);

                if (File.Exists(_metadataFilePath))
                {
                    File.Delete(_metadataFilePath);
                }
                File.Move(tempPath, _metadataFilePath);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"[IndexerError] Exception writing index file: {ex.Message}");
            }
        }

        private void LoadMetadataIndex()
        {
            _indexLock.EnterWriteLock();
            try
            {
                if (File.Exists(_metadataFilePath))
                {
                    string json = File.ReadAllText(_metadataFilePath);
                    var loaded = JsonSerializer.Deserialize<List<LogChunkMetadata>>(json);
                    if (loaded != null)
                    {
                        _metadataIndex.Clear();
                        _metadataIndex.AddRange(loaded);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"[IndexerError] Could not restore index file context. Initializing fresh: {ex.Message}");
            }
            finally
            {
                _indexLock.ExitWriteLock();
            }
        }

        public void Dispose()
        {
            FlushAllAsync().GetAwaiter().GetResult();
            _indexLock.Dispose();
        }
    }

    #endregion

    #region Pipeline Orchestrator Coordination Engine

    public sealed class EnterpriseLogPipeline : IDisposable
    {
        public ILogCollector Collector { get; }
        public IRealTimePatternMatcher Matcher { get; }
        public ILogIndexer Indexer { get; }

        private readonly CancellationTokenSource _cts = new();

        public EnterpriseLogPipeline(ILogCollector collector, IRealTimePatternMatcher matcher, ILogIndexer indexer)
        {
            Collector = collector;
            Matcher = matcher;
            Indexer = indexer;
        }

        public void InitializePipeline()
        {
            // Establish dynamic multi-destination consumer loops using safe handoffs
            Collector.StartProcessing(async logEvent =>
            {
                // 1. Send straight to pattern matches (CPU-bound)
                Matcher.Analyze(logEvent);

                // 2. Stream instantly into the file system index persistence worker
                await Indexer.WriteAsync(logEvent).ConfigureAwait(false);

            }, _cts.Token);
        }

        public void Dispose()
        {
            _cts.Cancel();
            Collector.Dispose();
            Indexer.Dispose();
            _cts.Dispose();
        }
    }

    #endregion

    #region Program Entrypoint & Simulation Demonstration Harness

    public static class Program
    {
        public static async Task Main()
        {
            Console.WriteLine("=== INITIALIZING ENTERPRISE LOG INGESTION PIPELINE ===");

            // Define directories inside physical runtime context
            string workingDirectory = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "LogStore");
            if (Directory.Exists(workingDirectory))
            {
                Directory.Delete(workingDirectory, true);
            }

            // Subsystem Dependencies Initialization
            var collector = new HighThroughputLogCollector(maxCapacity: 100000);

            // Set alert threshold: Alert if 5 or more Error+ logs occur inside any sliding window of 3 seconds
            var matcher = new RealTimePatternMatcher(
                windowDuration: TimeSpan.FromSeconds(3),
                anomalyThreshold: 5,
                targetSeverity: LogSeverity.Error
            );

            // Register Threat signatures (Regex match configurations)
            matcher.RegisterThreatPattern("SQL_INJECTION", @"\b(SELECT|INSERT|UPDATE|DELETE|UNION|DROP)\b");
            matcher.RegisterThreatPattern("PATH_TRAVERSAL", @"\.\./\.\.");
            matcher.RegisterThreatPattern("UNAUTHORIZED", @"\b(access denied|invalid authorization|forbidden)\b");

            // Subsystem 3: Persistence with micro-chunking limits to force active on-disk chunk generations
            var indexer = new CompressedLogIndexer(workingDirectory, maxLogsPerChunk: 500);

            // Wire up Orchestrator
            using var pipeline = new EnterpriseLogPipeline(collector, matcher, indexer);

            // Register Real-Time Alert Callbacks
            matcher.OnAnomalyDetected += (sender, args) =>
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine($"\n🚨 [ANOMALY ALERT] [{args.Timestamp:HH:mm:ss.fff}] -> {args.Message}\n");
                Console.ResetColor();
            };

            // Bootstrap Async Worker Pipeline Threads
            pipeline.InitializePipeline();

            // Run High Throughput Simulation
            CancellationTokenSource simulationCts = new CancellationTokenSource();
            Console.WriteLine("Ingestion engine active. Spawning concurrent simulation threads...");

            Task producerTask1 = SimulatingLogProducer(pipeline.Collector, "WebServer-01", 120, simulationCts.Token);
            Task producerTask2 = SimulatingLogProducer(pipeline.Collector, "DatabaseEngine-A", 150, simulationCts.Token);
            Task producerTask3 = SimulatingLogProducer(pipeline.Collector, "AuthenticationService", 80, simulationCts.Token);

            // Periodically report metrics inside terminal during live writes
            Task metricsReporter = Task.Run(async () =>
            {
                while (!simulationCts.Token.IsCancellationRequested)
                {
                    await Task.Delay(1000).ConfigureAwait(false);
                    var metrics = pipeline.Collector.GetPerformanceMetrics();
                    Console.ForegroundColor = ConsoleColor.Cyan;
                    Console.WriteLine($"[METRICS] Ingested: {metrics["Ingested"]} | Dropped: {metrics["Dropped"]} | Queue Depth: {metrics["CurrentQueueDepth"]}/{metrics["MaxCapacity"]}");
                    Console.ResetColor();
                }
            });

            // Run simulation for 8 seconds
            await Task.Delay(8000);

            Console.WriteLine("\nHalting producers...");
            await simulationCts.CancelAsync();

            try
            {
                await Task.WhenAll(producerTask1, producerTask2, producerTask3, metricsReporter);
            }
            catch (Exception) { /* catch graceful exits */ }

            Console.WriteLine("\nFlushing dynamic system buffers to disk memory stores...");
            await pipeline.Indexer.FlushAllAsync();

            Console.WriteLine("\nSimulated Log Operations Ingest Complete. Inspecting Physical Logs Metadata Index...");

            string metadataPath = Path.Combine(workingDirectory, "index.json");
            if (File.Exists(metadataPath))
            {
                string metadataContents = await File.ReadAllTextAsync(metadataPath);
                Console.ForegroundColor = ConsoleColor.Yellow;
                Console.WriteLine(metadataContents);
                Console.ResetColor();
            }

            // Running historical high performance queries
            Console.WriteLine("\nExecuting analytical search on compressed historical indices...");
            DateTime searchStart = DateTime.UtcNow.AddSeconds(-15);
            DateTime searchEnd = DateTime.UtcNow;

            var results = pipeline.Indexer.QueryHistoricalLogs(searchStart, searchEnd).ToList();
            Console.WriteLine($"Matched {results.Count} results within the timestamp window!");

            var threatMatches = results.Where(r => r.Message.Contains("UNION SELECT") || r.Message.Contains("access denied")).ToList();
            Console.ForegroundColor = ConsoleColor.Magenta;
            Console.WriteLine($"Detected threat footprints on historical scan: {threatMatches.Count} matches found!");
            foreach(var threat in threatMatches.Take(3))
            {
                 Console.WriteLine($" - ID: {threat.Id} | Comp: {threat.Component} | Msg: {threat.Message}");
            }
            Console.ResetColor();

            Console.WriteLine("\nSystem teardown successful. Press any key to exit.");
        }

        /// <summary>
        /// Simulation logic reproducing chaotic production telemetry environments.
        /// </summary>
        private static async Task SimulatingLogProducer(ILogCollector collector, string component, int delayMs, CancellationToken token)
        {
            var random = new Random();
            string[] routes = ["/api/users/login", "/api/transactions/process", "/assets/images/logo.png", "/admin/settings"];
            string[] normalMessages = ["GET connection established", "Cache hit ratio 94%", "Active threads pool normalized", "Keep-alive payload validated"];
            string[] SQLThreatMessages = ["SELECT * FROM Users WHERE id = 1 UNION SELECT password FROM admin", "'; DROP TABLE Transactions; --"];
            string[] authThreatMessages = ["invalid authorization bearer credentials provided", "access denied for principal: user_anonymous"];

            while (!token.IsCancellationRequested)
            {
                double roll = random.NextDouble();
                LogSeverity severity = LogSeverity.Info;
                string message = normalMessages[random.Next(normalMessages.Length)];
                string rawPayload = $"{{\"route\": \"{routes[random.Next(routes.Length)]}\", \"latency\": {random.Next(1, 45)} }}";

                if (roll > 0.95) // 5% Critical Failures (Triggers Anomaly Sliding Window Alert)
                {
                    severity = LogSeverity.Error;
                    message = $"System Internal Outage Exception: Connection pool exhausted. Timeout during resource handoff.";
                    rawPayload = "{\"stackTrace\": \"NullReferenceException at Service.Data.Connector.ExecuteReader()\"}";
                }
                else if (roll > 0.90 && roll <= 0.95) // 5% Target malicious footprint
                {
                    severity = LogSeverity.Warning;
                    message = random.Next(2) == 0 
                        ? SQLThreatMessages[random.Next(SQLThreatMessages.Length)] 
                        : authThreatMessages[random.Next(authThreatMessages.Length)];
                }
                else if (roll > 0.75 && roll <= 0.90) // 15% Normal Warnings
                {
                    severity = LogSeverity.Warning;
                    message = "High GC heap memory usage observed. Running threshold limits optimization routine.";
                }

                collector.TrySubmit(severity, component, message, rawPayload);
                await Task.Delay(delayMs, token).ConfigureAwait(false);
            }
        }
    }

    #endregion
}
```

